<?php
declare(strict_types=1);namespace App\Http\Controllers\TeachingAssignments;use App\Http\Controllers\Controller;use App\Http\Requests\TeachingAssignments\SaveAdditionalDutyRequest;use App\Models\{AdditionalDuty,TeachingAssignmentSet};use App\Services\TeachingAssignments\TeachingAssignmentDutyService;use Illuminate\Http\RedirectResponse;
class TeachingAssignmentDutyController extends Controller {public function store(SaveAdditionalDutyRequest $r,TeachingAssignmentDutyService $s):RedirectResponse{$set=TeachingAssignmentSet::findOrFail($r->validated('assignment_set_id'));$s->save($r->user(),$set,$r->validated());return back()->with('success','Tugas tambahan berhasil disimpan.');}public function update(SaveAdditionalDutyRequest $r,AdditionalDuty $duty,TeachingAssignmentDutyService $s):RedirectResponse{$s->save($r->user(),$duty->assignmentSet,$r->validated(),$duty);return back()->with('success','Tugas tambahan berhasil diperbarui.');}}
